Definition sgi_ok (s : Segment) (g : sgi) : Prop :=
  sg_seg g = s /\ φ (sg_lo g) = Z.of_N (seg_base s) /\ φ (sg_hi g) = Z.of_N (seg_base s) + Z.of_N (seg_size s) /\ sg_r g = seg_readable s.
